// Turn a lookup table into code and files the robot programmers can paste in.

const M_TO_IN = 39.3700787;

function fmt(x, digits = 3) {
  return Number(x).toFixed(digits);
}

function keyed(rows, unit) {
  return rows.filter((r) => r.ok).map((r) => ({
    ...r,
    key: unit === 'in' ? r.distance * M_TO_IN : r.distance,
  }));
}

function hasHood(rows) {
  return rows.some((r) => r.ok && r.hood != null && r.hood !== '');
}

function header(meta) {
  const lines = [
    'Generated by Trajectory (trajectory.meckman.org), a Meckman Lab experiment.',
    `Built ${meta.date} from ${meta.shots} measured shots.`,
    `Goal height ${fmt(meta.goalHeight, 2)} m, launch height ${fmt(meta.launchHeight, 2)} m.`,
    `Setpoint units: ${meta.setpointUnit}. Re-measure after any mechanical change to the launcher.`,
  ];
  return lines;
}

// FRC: WPILib InterpolatingDoubleTreeMap, keyed by distance.
export function toFrcJava(rows, meta, { className = 'ShotTable', unit = 'm' } = {}) {
  const r = keyed(rows, unit);
  const hood = hasHood(rows);
  const u = unit === 'in' ? 'Inches' : 'Meters';
  const out = [];
  out.push('package frc.robot;', '');
  out.push('import edu.wpi.first.math.interpolation.InterpolatingDoubleTreeMap;', '');
  out.push('/**');
  for (const l of header(meta)) out.push(` * ${l}`);
  out.push(' */');
  out.push(`public final class ${className} {`);
  out.push(`  /** Distance to goal (${unit}) to launcher setpoint (${meta.setpointUnit}). */`);
  out.push('  public static final InterpolatingDoubleTreeMap SETPOINT = new InterpolatingDoubleTreeMap();');
  if (hood) out.push('  /** Distance to goal to hood setting. */', '  public static final InterpolatingDoubleTreeMap HOOD = new InterpolatingDoubleTreeMap();');
  out.push('', '  static {');
  for (const row of r) {
    out.push(`    SETPOINT.put(${fmt(row.key)}, ${fmt(row.setpoint, 1)});${row.extrapolated ? ' // extrapolated, verify on the field' : ''}`);
    if (hood) out.push(`    HOOD.put(${fmt(row.key)}, ${fmt(Number(row.hood), 2)});`);
  }
  out.push('  }', '');
  out.push(`  public static double setpointFor${u}(double distance) {`, '    return SETPOINT.get(distance);', '  }');
  if (hood) out.push('', `  public static double hoodFor${u}(double distance) {`, '    return HOOD.get(distance);', '  }');
  out.push('', `  private ${className}() {}`, '}', '');
  return out.join('\n');
}

// FTC: plain arrays plus a clamped linear interpolation helper (no WPILib on the Control Hub).
export function toFtcJava(rows, meta, { className = 'ShotTable', unit = 'in' } = {}) {
  const r = keyed(rows, unit);
  const hood = hasHood(rows);
  const u = unit === 'in' ? 'Inches' : 'Meters';
  const arr = (vals, d) => vals.map((v) => fmt(v, d)).join(', ');
  const out = [];
  out.push('package org.firstinspires.ftc.teamcode;', '');
  out.push('/**');
  for (const l of header(meta)) out.push(` * ${l}`);
  out.push(' */');
  out.push(`public final class ${className} {`);
  out.push(`  /** Distance to goal (${unit}), ascending. */`);
  out.push(`  public static final double[] DISTANCE = { ${arr(r.map((x) => x.key), 3)} };`);
  out.push(`  /** Launcher setpoint (${meta.setpointUnit}) at each distance. */`);
  out.push(`  public static final double[] SETPOINT = { ${arr(r.map((x) => x.setpoint), 1)} };`);
  if (hood) out.push(`  /** Hood setting at each distance. */`, `  public static final double[] HOOD = { ${arr(r.map((x) => Number(x.hood)), 2)} };`);
  out.push('');
  out.push(`  public static double setpointFor${u}(double distance) {`, '    return lerp(DISTANCE, SETPOINT, distance);', '  }');
  if (hood) out.push('', `  public static double hoodFor${u}(double distance) {`, '    return lerp(DISTANCE, HOOD, distance);', '  }');
  out.push('');
  out.push('  /** Linear interpolation, clamped to the ends of the table. */');
  out.push('  public static double lerp(double[] xs, double[] ys, double x) {');
  out.push('    if (x <= xs[0]) return ys[0];');
  out.push('    int last = xs.length - 1;');
  out.push('    if (x >= xs[last]) return ys[last];');
  out.push('    for (int i = 1; i <= last; i++) {');
  out.push('      if (x <= xs[i]) {');
  out.push('        double f = (x - xs[i - 1]) / (xs[i] - xs[i - 1]);');
  out.push('        return ys[i - 1] + f * (ys[i] - ys[i - 1]);');
  out.push('      }');
  out.push('    }');
  out.push('    return ys[last];');
  out.push('  }', '', `  private ${className}() {}`, '}', '');
  return out.join('\n');
}

export function toCsv(rows, { unit = 'm' } = {}) {
  const lines = [`distance_${unit},hood,setpoint,exit_speed_mps,launch_angle_deg,entry_angle_deg,flight_time_s,extrapolated`];
  for (const r of keyed(rows, unit)) {
    lines.push([fmt(r.key), r.hood ?? '', fmt(r.setpoint, 1), fmt(r.v0), fmt(r.angleDeg, 2), fmt(r.entryAngleDeg, 2), fmt(r.flightTime), r.extrapolated ? 'yes' : 'no'].join(','));
  }
  return lines.join('\n') + '\n';
}

export function toJson(rows, meta) {
  return JSON.stringify({ meta, rows: rows.filter((r) => r.ok) }, null, 2) + '\n';
}

// Per-shot export in the fixed shootout format, so all three solutions can be compared.
export function shotToCsv(shot) {
  const f = shot.fit || {};
  const lines = [
    '# trajectory-shot v1',
    `# shot,${shot.id}`,
    `# clip,${shot.clipName ?? ''}`,
    `# model,${f.model ?? ''}`,
    `# v0_mps,${fmt(f.v0 ?? NaN, 4)}`,
    `# angle_deg,${fmt(f.angleDeg ?? NaN, 3)}`,
    `# g_fit_mps2,${fmt(shot.ballistic?.g ?? NaN, 3)}`,
    `# rmse_m,${fmt(f.rmse ?? NaN, 5)}`,
    `# seconds_to_result,${fmt(shot.secondsToResult ?? NaN, 1)}`,
    't_s,x_m,y_m,confidence,excluded',
  ];
  for (const p of shot.points || []) {
    lines.push([fmt(p.t, 5), fmt(p.x, 5), fmt(p.y, 5), fmt(p.conf ?? 1, 2), p.off ? 1 : 0].join(','));
  }
  return lines.join('\n') + '\n';
}
